\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  \endash 195\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22   \plain \f1\b\lang1033\fs22   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Expositio cum dubiis super quartam fen primi canonis Avicennae }}
