\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Gregorius (IX.) episcopus ... episcopo Bononiensi}}\plain \f1\i\lang1033\fs22   ... {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ascendit de mari bestia blasphemie}}\plain \f1\i\lang1033\fs22  ... Datum Laterano ydus VII Junii pontificatus nostri anno tercio decimo\plain \f1\lang1033\fs22   (7. Juni 1239). \endash  Druck: MGH Epist. pont. I Nr. 750;
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (147\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  \endash 148\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ){\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17  Fredericus (II.) dei gracia Romanorum imperator}}\plain \f1\lang1033\fs22  ... \plain \f1\i\lang1033\fs22  vniuersis venerabilibus sancte Romane ecclesie ... salutem et sincere dileccionis affectum. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Commune (!) omnium principum orbis terre leticiam}}\plain \f1\i\lang1033\fs22  ... Datum Cremone II Decembris XI indiccione\plain \f1\lang1033\fs22   (2. Dezember 1237). \endash  Druck: \plain \f1\scaps\lang1033\fs22 Huillard/ Breholles\plain \f1\lang1033\fs22 , Historia diplomatica Friderici II., Paris 1854 Bd. V,1 S. 142. \endash  \plain \f1\scaps\lang1033\fs22 B\plain \f1\scaps\lang1033\fs22 \u246 \'f6\plain \f1\scaps\lang1033\fs22 hmer/Ficker/Winkelmann\plain \f1\lang1033\fs22 , Regesta imperii, Innsbruck 1881\endash 1901, V, 2290;
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (148\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  \endash 152\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 )\plain \f1\i\lang1033\fs22   {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Imperator Fridericus excusat se a criminibus}}\plain \f1\i\lang1033\fs22  ... {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 In admiracionem vertitur vehementem}}\plain \f1\lang1033\fs22   \endash  Druck: MGH Const. II Nr. 116;
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (152\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  \endash 153\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ) \plain \f1\i\lang1033\fs22  Karolus \plain \f1\lang1033\fs22  (\plain \f1\scaps\lang1033\fs22 Karl I. von Anjou\plain \f1\lang1033\fs22 )\plain \f1\i\lang1033\fs22   et cetera G\plain \f1\lang1033\fs22  [uilelmo] \plain \f1\i\lang1033\fs22  cardinalis\plain \f1\lang1033\fs22   (!, Kardinalpriester \plain \f1\scaps\lang1033\fs22 Wilhelm von S. Marco\plain \f1\lang1033\fs22 ) {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 In penitencia deflere reatum ex contagioso scelere}}\plain \f1\i\lang1033\fs22  ... in vno scelere virtutum omnium euersorum\plain \f1\lang1033\fs22 . \endash  Verfa\u223 \'dft kurz nach dem 12. M\u228 \'e4rz 1278. Vgl.\plain \f1\scaps\lang1033\fs22  F. Baethgen\plain \f1\lang1033\fs22 , Ein Pamphlet Karls I. von Anjou zur Wahl Papst Nikolaus' III. In: Sb. d. Bayer. Ak. d. Wissenschaften, Phil.-hist. Kl. 1960 H.7 S.18;
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (153\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs22 )  \plain \f1\i\lang1033\fs22  Suo domino R\plain \f1\lang1033\fs22  [ichardo] \plain \f1\i\lang1033\fs22  apostolice sedis notario suus Daniel. Fortem in aduersis animum ... adhesit et a tribu\plain \f2\lang1033\fs22 \u186 \'ba\plain \f1\lang1033\fs22   (bricht ab) \endash  Schreiben eines Kurialen an den apostolischen Notar Richard, kurz nach dem 12. M\u228 \'e4rz 1278. Vgl. \plain \f1\scaps\lang1033\fs22 F. Baethgen\plain \f1\lang1033\fs22   a. a. O. S. 22.}

