\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (204\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs22  \endash 213\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs22 )  \plain \f1\scaps\lang1033\fs22 Peregrinus de Oppeln. \plain \f1\lang1033\fs22   >\plain \f1\i\lang1033\fs22  De nouo sacerdote\plain \f1\lang1033\fs22  <{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17  Hodie incipiam te exaltare coram omni populo Israel Josue 3o (7). Verbum istud quondam dixerat dominus}}\plain \f1\i\lang1033\fs22   Josue \plain \f1\lang1033\fs22 ... \endash  vgl. zu M\u252 \'fcnchen UB 2\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs22   cod. 54, 87\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs22 . \endash  \plain \f1\scaps\lang1033\fs22 Schneyer\plain \f1\lang1033\fs22 , Repertorium 4 S. 564 Nr. 194; 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (212\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs22 ) \plain \f1\scaps\lang1033\fs22 Petrus Plank. \plain \f1\lang1033\fs22  >\plain \f1\i\lang1033\fs22  Alius sermo de nouo sacerdote\plain \f1\lang1033\fs22  < {\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Noua lux oriri visa est gaudium honor Hester (8, 6). Verba ista bene competunt presenti congregacioni quia nobis lux noua orta est}}\plain \f1\i\lang1033\fs22  ...\plain \f1\lang1033\fs22  ; (212\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs22 ) >\plain \f1\i\lang1033\fs22  De eodem\plain \f1\lang1033\fs22  < {\field{\*\fldinst HYPERLINK "hida://5650[16].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Vas eleccionis est mihi iste ut portet nomen meum coram regibus et principibus Actus (9, 15). Verba iam dicta dicit dominus ad Anianam dum Paulum conuertisset}}\plain \f1\lang1033\fs22  ... \endash  vgl. zu M\u252 \'fcnchen UB 2\plain \f1\super\lang1033\fs24 o \plain \f1\lang1033\fs22  cod. 64, 272\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs22 . \endash  \plain \f1\scaps\lang1033\fs22 Schneyer\plain \f1\lang1033\fs22 , Repertorium (CD) Nr. 468, 469;
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (213\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs22  \endash 215\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs22 ) >\plain \f1\i\lang1033\fs22  De corpore Christi\plain \f1\lang1033\fs22  < {\field{\*\fldinst HYPERLINK "hida://5650[18].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Venite comedite panem meum et bibite vinum quod miscui uobis  (Prv 9, 5). Verba ista leguntur in Canticis et per ea inuitat nos dominus ad mensam suam }}\plain \f1\lang1033\fs22 ...; (213\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs22 ) >\plain \f1\i\lang1033\fs22  De corpore Christi\plain \f1\lang1033\fs22  <\plain \f1\i\lang1033\fs22   {\field{\*\fldinst HYPERLINK "hida://5650[12].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Paratur nobis mensa domini aduersus omnes qui tribulant nos (nach Ps 22, 5). Verba proposita scripta sunt de festo presenti quod ecclesia celebratur de corpore Christi }}\plain \f1\lang1033\fs22 ...; (213\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs22 ) >\plain \f1\i\lang1033\fs22  De eodem\plain \f1\lang1033\fs22  < {\field{\*\fldinst HYPERLINK "hida://5650[11].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Panem celi dedit eis panem angelorum manducauit }}{\field{\*\fldinst HYPERLINK "hida://5650[11].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 (Ps 77, 24\endash 25).}}\plain \f1\i\lang1033\fs22   {\field{\*\fldinst HYPERLINK "hida://5650[11].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Quod quinquaginta horum filiorum Israel subitanea morte mortui sunt in deserto}}\plain \f1\lang1033\fs22  ...; (214\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs22 ) >\plain \f1\i\lang1033\fs22  Miracula de corpore Christi\plain \f1\lang1033\fs22  < {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Notandum quod VII miracula fuerunt in corpore Christi et sanguine: Primum quod substancia panis mutatur in corpus Christi visibiliter }}\plain \f1\lang1033\fs22 ...;
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (215\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs22 ) Schreibereintrag: >\plain \f1\i\lang1033\fs22  Got der geb mir ain gcz news jar\plain \f1\lang1033\fs22  < \endash  215\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs22  \endash 215\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22   leer; 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (216\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs22  \endash 218\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs22 ) >\plain \f1\i\lang1033\fs22  Sermo quando placet\plain \f1\lang1033\fs22  < {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Beatus vir qui inuenit sapienciam Proverb. 3o (13). Ex quibus verbis sciendum quod sapientes illi maxime laudantur}}\plain \f1\i\lang1033\fs22   qui sciuerunt se cauere ab astuciis demonum\plain \f1\lang1033\fs22  ...\endash ... ; 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (218\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs22  \endash 233\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs22 ) De festis domini. \plain \f1\i\lang1033\fs22  >Sequitur sermo de natiuitate domini\plain \f1\lang1033\fs22  < {\field{\*\fldinst HYPERLINK "hida://5650[13].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Paruulus natus est nobis et filius datus est nobis Ysaie IXo (6). In quibus verbis duo considerare debemus: Primo Christi humanitatem}}\plain \f1\lang1033\fs22  ...; \endash  (220\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  \endash 221\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ) Deutsche Randglosse; (221\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs22 ) >\plain \f1\i\lang1033\fs22  Sequitur sermo in natiuitate domini\plain \f1\lang1033\fs22  < {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Exiit edictum a caesare Augusto ut describeretur vniuersus orbis Luce IIo (1). Vbi scire debetis filii karissimi quod moris est quando alicui magno rege (!) uel principi filius primogenitus fuerit}}\plain \f1\i\lang1033\fs22   \plain \f1\lang1033\fs22 ...; (224\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs22 ) >\plain \f1\i\lang1033\fs22  Sermo in natiuitate Christi\plain \f1\lang1033\fs22  < (224\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs22 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Annuncio uobis gaudium magnum quia natus est uobis saluator mundi ... Luce II (10). Ex quibus verbis sciendum quod angelus hec verba}}\plain \f1\i\lang1033\fs22   \plain \f1\lang1033\fs22 ...; (227\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs22 ) >\plain \f1\i\lang1033\fs22  Sermo in circumcisione\plain \f1\lang1033\fs22  < {\field{\*\fldinst HYPERLINK "hida://5650[14].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Postquam consummati sunt dies octo etc. Luce II (21). Vbi sciendum quod hodie recolimus tam festa primo dominice natiuitatis  octauam}}\plain \f1\i\lang1033\fs22  ...\plain \f1\lang1033\fs22  ;\plain \f1\i\lang1033\fs22   \plain \f1\lang1033\fs22  (230\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs22 ) >\plain \f1\i\lang1033\fs22  In epyphania domini sermo bonus et vtilis\plain \f1\lang1033\fs22  < {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Cvm natus esset Jhesus in Bethlehem Iudee in diebus Herodis ... Math. IIo (1). Vbi sciendum quod si volumus querere regem nostrum et puerum qui natus est nobis}}\plain \f1\lang1033\fs22  ...;
